text:
{
  "tasks": [
    {
      "task_id": "T01",
      "title": "已解决工单按优先级数量统计及Top2排名",
      "business_question": "在只看已解决工单的约束下，各优先级的工单数量是多少？请按降序取前两名。",
      "priority": "P0",
      "priority_reason": "删除此任务将无法回答核心问题“统计已解决工单在各优先级下的数量，并按降序取前两名”，且无法支持相关决策。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0003",
                "operator": "eq",
                "value": "已解决"
              }
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "ticket_count"
              }
            ],
            "dimensions": [
              "field_0004"
            ]
          }
        },
        {
          "step_id": "S03",
          "operation": "sort",
          "params": {
            "field": "ticket_count",
            "direction": "desc"
          }
        },
        {
          "step_id": "S04",
          "operation": "top_n",
          "params": {
            "field": "ticket_count",
            "direction": "desc",
            "n": 2
          }
        }
      ]
    }
  ]
}
